CREATE OR REPLACE ALGORITHM=UNDEFINED DEFINER=`craftcore`@`%` SQL SECURITY DEFINER VIEW v_market AS select c.item AS item,CASE WHEN coalesce(l.lock_buy,0)=1 THEN NULL ELSE c.buy_price END AS buy_price,CASE WHEN coalesce(l.lock_sell,0)=1 THEN NULL ELSE c.sell_price END AS sell_price,c.base_price AS base_price,coalesce(e.qty,0) AS volume_24h_qty,coalesce(e.cp,0) AS volume_24h_cp,coalesce(e.trades,0) AS trades_24h,(c.sell_price - h.avg_price) / nullif(h.avg_price,0) * 100 AS change_24h_pct,c.updated_at AS updated_at,CASE WHEN coalesce(l.lock_buy,0)=1 THEN 0 ELSE 1 END AS buy_enabled,CASE WHEN coalesce(l.lock_sell,0)=1 THEN 0 ELSE 1 END AS sell_enabled from market_catalog c left join (select item,sum(qty) AS qty,sum(total_cp) AS cp,count(0) AS trades from market_events where ts >= unix_timestamp() - 86400 group by item) e on e.item = c.item left join market_price_history h on h.item = c.item and h.hour_ts = (select max(h2.hour_ts) from market_price_history h2 where h2.item=c.item and h2.hour_ts <= unix_timestamp() - 86400) left join market_locks l on l.item=c.item;
